targets=[(5,5),(1,14),(14,14),(5,19),(16,36),(16,54),(23,55),(20,46)]
def cover(cx,cy,t,vhalf=13,hhalf=13):
    x,y=t
    return (abs(x-cx)<=1 and abs(y-cy)<=vhalf) or (abs(y-cy)<=1 and abs(x-cx)<=hhalf)
